import os
import unicodedata
from pathlib import PurePosixPath
from flask import Flask, request, jsonify, abort
import hashlib
import hmac
import time

app = Flask(__name__)

SECRET_KEY = os.environ.get('SECRET_KEY', os.urandom(32))
BASE_DIR = '/var/www/uploads'
ALLOWED_EXTENSIONS = {'.txt', '.pdf', '.png', '.jpg', '.doc'}

def constant_time_compare(a, b):
    return hmac.compare_digest(a.encode() if isinstance(a, str) else a,
                               b.encode() if isinstance(b, str) else b)

def generate_token(username):
    ts = str(int(time.time()) // 300)
    return hmac.new(SECRET_KEY if isinstance(SECRET_KEY, bytes) else SECRET_KEY.encode(),
                    f"{username}:{ts}".encode(), hashlib.sha256).hexdigest()

def verify_token(username, token):
    expected = generate_token(username)
    return constant_time_compare(expected, token)

def sanitize_filename(filename):
    """Sanitize filename to prevent path traversal.
    Uses NFKC normalization for consistent Unicode handling,
    then validates no path separators remain."""
    # Step 1: Strip null bytes
    filename = filename.replace('\x00', '')
    # Step 2: Unicode NFKC normalization for consistent representation
    filename = unicodedata.normalize('NFKC', filename)
    # Step 3: Reject any path separators
    if '/' in filename or '\\' in filename:
        return None
    # Step 4: Reject path traversal attempts
    if '..' in filename:
        return None
    # Step 5: Validate extension
    ext = os.path.splitext(filename)[1].lower()
    if ext not in ALLOWED_EXTENSIONS:
        return None
    return filename

def validate_path_component(component):
    """Additional validation: ensure resolved path stays within BASE_DIR."""
    # Check the component doesn't start with a dot (hidden files)
    if component.startswith('.'):
        return False
    # Check length
    if len(component) > 255:
        return False
    return True

def build_safe_path(username, filename):
    """Build a safe file path within the user's directory."""
    # Sanitize the filename first
    clean_name = sanitize_filename(filename)
    if clean_name is None:
        return None
    # Validate path component
    if not validate_path_component(clean_name):
        return None
    # Build the path using os.path.join
    user_dir = os.path.join(BASE_DIR, username)
    full_path = os.path.join(user_dir, clean_name)
    # Final check: ensure the resolved path is under BASE_DIR
    resolved = os.path.realpath(full_path)
    if not resolved.startswith(os.path.realpath(BASE_DIR)):
        return None
    return full_path

@app.route('/api/files/<username>', methods=['GET'])
def list_files(username):
    token = request.headers.get('X-Auth-Token', '')
    if not verify_token(username, token):
        abort(403)
    user_dir = os.path.join(BASE_DIR, username)
    if not os.path.isdir(user_dir):
        return jsonify([])
    files = os.listdir(user_dir)
    return jsonify(files)

@app.route('/api/files/<username>/read', methods=['POST'])
def read_file(username):
    token = request.headers.get('X-Auth-Token', '')
    if not verify_token(username, token):
        abort(403)
    data = request.get_json()
    if not data or 'filename' not in data:
        abort(400)
    filename = data['filename']
    safe_path = build_safe_path(username, filename)
    if safe_path is None:
        abort(403)
    # TOCTOU: validate then open - but the real issue is elsewhere
    if not os.path.isfile(safe_path):
        abort(404)
    with open(safe_path, 'r') as f:
        content = f.read()
    return jsonify({'content': content, 'filename': filename})

@app.route('/api/files/<username>/write', methods=['POST'])
def write_file(username):
    token = request.headers.get('X-Auth-Token', '')
    if not verify_token(username, token):
        abort(403)
    data = request.get_json()
    if not data or 'filename' not in data or 'content' not in data:
        abort(400)
    filename = data['filename']
    content = data['content']
    safe_path = build_safe_path(username, filename)
    if safe_path is None:
        abort(403)
    user_dir = os.path.join(BASE_DIR, username)
    os.makedirs(user_dir, exist_ok=True)
    with open(safe_path, 'w') as f:
        f.write(content)
    return jsonify({'status': 'ok', 'path': safe_path})

@app.route('/api/files/<username>/rename', methods=['POST'])
def rename_file(username):
    token = request.headers.get('X-Auth-Token', '')
    if not verify_token(username, token):
        abort(403)
    data = request.get_json()
    if not data or 'old_name' not in data or 'new_name' not in data:
        abort(400)
    old_name = data['old_name']
    new_name = data['new_name']
    old_path = build_safe_path(username, old_name)
    new_path = build_safe_path(username, new_name)
    if old_path is None or new_path is None:
        abort(403)
    if not os.path.isfile(old_path):
        abort(404)
    os.rename(old_path, new_path)
    return jsonify({'status': 'ok'})

@app.route('/api/files/<username>/copy', methods=['POST'])
def copy_file(username):
    """Copy a file, supporting cross-directory copies for shared folders."""
    token = request.headers.get('X-Auth-Token', '')
    if not verify_token(username, token):
        abort(403)
    data = request.get_json()
    if not data or 'source' not in data or 'dest_name' not in data:
        abort(400)
    source = data['source']
    dest_name = data['dest_name']
    # Source validation: normalize then check
    source_normalized = unicodedata.normalize('NFC', source)
    # Remove any null bytes
    source_normalized = source_normalized.replace('\x00', '')
    # Build source path - allow reading from shared directories
    source_path = os.path.join(BASE_DIR, source_normalized)
    # Security check: source must be under BASE_DIR
    if not os.path.realpath(source_path).startswith(os.path.realpath(BASE_DIR)):
        abort(403)
    # Destination uses full sanitization
    dest_path = build_safe_path(username, dest_name)
    if dest_path is None:
        abort(403)
    if not os.path.isfile(source_path):
        abort(404)
    import shutil
    shutil.copy2(source_path, dest_path)
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
